pub const BrowserEngine = struct {
    allocator: std.mem.Allocator,
    process: std.process.Child,
    stdout_reader: std.io.BufferedReader(4096, std.fs.File.Reader),

    pub fn init(allocator: std.mem.Allocator, binary_path: []const u8) !BrowserEngine {
        const argv = [_][]const u8{ binary_path, "serve", "--host", "127.0.0.1", "--port", "9222" };

        var child = std.process.Child.init(&argv, allocator);
        child.stdout_behavior = .Pipe;
        child.stderr_behavior = .Pipe;

        try child.spawn();

        return BrowserEngine{
            .allocator = allocator,
            .process = child,
            .stdout_reader = std.io.bufferedReader(child.stdout.?.reader()),
        };
    }

    pub fn fetchPage(self: *BrowserEngine, url: []const u8) !*types.Node {
        _ = self;

        const root = try types.Node.init(self.allocator);
        root.type = .Document;

        const body = try types.Node.init(self.allocator);
        body.tag = "body";
        body.computed_style.display = .Block;
        body.computed_style.padding = 10;

        const h1 = try types.Node.init(self.allocator);
        h1.tag = "h1";
        h1.text_content = url; 
        h1.computed_style.font_size = 24;
        h1.computed_style.display = .Block;

        const p = try types.Node.init(self.allocator);
        p.tag = "p";
        p.text_content = "Content loaded via Lightpanda simulation.";
        p.computed_style.display = .Block;

        try body.children.append(h1);
        try body.children.append(p);
        try root.children.append(body);

        return root;
    }

    pub fn deinit(self: *BrowserEngine) void {
        _ = self.process.kill() catch {};
    }
};
