const std = @import("std");
const types = @import("types.zig");

pub const LayoutEngine = struct {
    viewport_width: f32,
    viewport_height: f32,

    pub fn init(width: f32, height: f32) LayoutEngine {
        return .{
            .viewport_width = width,
            .viewport_height = height,
        };
    }

    pub fn calculateLayout(self: *LayoutEngine, root: *types.Node) void {
        var cursor_y: f32 = 0;
        self.processNode(root, 0, &cursor_y, self.viewport_width);
    }

    fn processNode(self: *LayoutEngine, node: *types.Node, x: f32, y: *f32, available_width: f32) void {
        node.layout_box.x = x + node.computed_style.margin;
        node.layout_box.y = y.* + node.computed_style.margin;

        const content_width = available_width - (node.computed_style.margin * 2) - (node.computed_style.padding * 2);
        node.layout_box.width = content_width;

        var current_height: f32 = 0;

        if (node.text_content.len > 0) {
            current_height = node.computed_style.font_size * 1.2;
        }

        const child_x = node.layout_box.x + node.computed_style.padding;
        var child_y = node.layout_box.y + node.computed_style.padding + current_height;

        for (node.children.items) |child| {
            self.processNode(child, child_x, &child_y, content_width);
        }

        if (node.children.items.len > 0) {
            current_height += (child_y - (node.layout_box.y + node.computed_style.padding));
        }

        node.layout_box.height = current_height + (node.computed_style.padding * 2);

        if (node.computed_style.display == .Block) {
             y.* += node.layout_box.height + (node.computed_style.margin * 2);
        }
    }
};
