const std = @import("std");
const mach = @import("mach");
const types = @import("types.zig");

pub const App = struct {
    engine: *mach.Core,
    pipeline: mach.gpu.RenderPipeline,
    queue: *mach.gpu.Queue,
    root_node: ?*types.Node,

    pub fn init(engine: *mach.Core) !App {
        const shader_module = engine.device.createShaderModule(&.{
            .label = "rect_shader",
            .code = .{ .wgsl = 
                \\@vertex fn vs_main(@builtin(vertex_index) VertexIndex : u32) -> @builtin(position) vec4<f32> {
                \\    var pos = array<vec2<f32>, 4>(
                \\        vec2<f32>(-1.0, 1.0),
                \\        vec2<f32>(1.0, 1.0),
                \\        vec2<f32>(-1.0, -1.0),
                \\        vec2<f32>(1.0, -1.0)
                \\    );
                \\    return vec4<f32>(pos[VertexIndex], 0.0, 1.0);
                \\}
                \\@fragment fn fs_main() -> @location(0) vec4<f32> {
                \\    return vec4<f32>(1.0, 0.0, 0.0, 1.0);
                \\}
            },
        });
        defer shader_module.release();

        const pipeline_layout = engine.device.createPipelineLayout(&.{
            .bind_group_layouts = &.{},
        });
        defer pipeline_layout.release();

        const pipeline = engine.device.createRenderPipeline(&.{
            .label = "render_pipeline",
            .layout = pipeline_layout,
            .vertex = .{
                .module = shader_module,
                .entry_point = "vs_main",
            },
            .fragment = &.{
                .module = shader_module,
                .entry_point = "fs_main",
                .targets = &.{.{ .format = engine.descriptor.format }},
            },
        });

        return App{
            .engine = engine,
            .pipeline = pipeline,
            .queue = engine.device.getQueue(),
            .root_node = null,
        };
    }

    pub fn deinit(self: *App) void {
        self.pipeline.release();
        self.queue.release();
    }

    pub fn update(self: *App) !bool {
        const encoder = self.engine.device.createCommandEncoder(null);
        defer encoder.release();

        const back_buffer_view = self.engine.swap_chain.getCurrentTextureView();
        defer back_buffer_view.release();

        const color_attachment = mach.gpu.RenderPassColorAttachment{
            .view = back_buffer_view,
            .load_op = .clear,
            .store_op = .store,
            .clear_value = .{ .r = 0.9, .g = 0.9, .b = 0.9, .a = 1.0 },
        };

        const render_pass = encoder.beginRenderPass(&.{
            .color_attachments = &.{color_attachment},
        });

        render_pass.setPipeline(self.pipeline);
        render_pass.draw(4, 1, 0, 0);
        render_pass.end();
        render_pass.release();

        const command_buffer = encoder.finish(null);
        defer command_buffer.release();

        self.queue.submit(&.{command_buffer});
        self.engine.swap_chain.present();

        return false;
    }
};
