        return BrowserEngine{
            .allocator = allocator,
            .binary_path = binary_path,
        };
    }

    pub fn fetchPage(self: *BrowserEngine, url: []const u8) !*types.Node {
        const argv = [_][]const u8{ self.binary_path, "fetch", "--dump", url };

        var child = std.process.Child.init(&argv, self.allocator);
        child.stdout_behavior = .Pipe;
        child.stderr_behavior = .Pipe;

        try child.spawn();

        var stdout = std.ArrayList(u8).init(self.allocator);
        defer stdout.deinit();

        var buf: [4096]u8 = undefined;
        while (true) {
            const bytes_read = try child.stdout.?.read(&buf);
            if (bytes_read == 0) break;
            try stdout.appendSlice(buf[0..bytes_read]);
        }

        _ = try child.wait();

        const html_content = try stdout.toOwnedSlice();

        const root_node = try html_parser.parse(self.allocator, html_content);
        return root_node;
    }
};
