const std = @import("std");
const types = @import("types.zig");

pub fn parse(allocator: std.mem.Allocator, html: []const u8) !*types.Node {
    var root = try types.Node.init(allocator);
    root.type = .Document;

    var current_node = root;
    var i: usize = 0;

    while (i < html.len) {
        if (html[i] == '<') {
            if (i + 1 < html.len and html[i + 1] == '/') {
                const close_start = i + 2;
                var close_end = close_start;
                while (close_end < html.len and html[close_end] != '>') : (close_end += 1) {}

                if (current_node.parent) |parent| {
                    current_node = parent;
                }
                i = close_end + 1;
            } else if (i + 3 < html.len and std.mem.eql(u8, html[i..i+4], "<!--")) {
                 var comment_end = i + 4;
                 while (comment_end + 2 < html.len) : (comment_end += 1) {
                     if (std.mem.eql(u8, html[comment_end..comment_end+3], "-->")) {
                         comment_end += 3;
                         break;
                     }
                 }
                 i = comment_end;
            } else {
                const tag_start = i + 1;
                var tag_end = tag_start;
                while (tag_end < html.len and html[tag_end] != ' ' and html[tag_end] != '>') : (tag_end += 1) {}

                const tag_name = html[tag_start..tag_end];
                var new_node = try types.Node.init(allocator);
                new_node.tag = try allocator.dupe(u8, tag_name);
                new_node.parent = current_node;

                if (std.mem.eql(u8, tag_name, "div")) new_node.computed_style.display = .Block;
                if (std.mem.eql(u8, tag_name, "p")) {
                    new_node.computed_style.display = .Block;
                    new_node.computed_style.margin = 10;
                }
                if (std.mem.eql(u8, tag_name, "h1")) {
                    new_node.computed_style.display = .Block;
                    new_node.computed_style.font_size = 32;
                    new_node.computed_style.margin = 20;
                }
                if (std.mem.eql(u8, tag_name, "a")) {
                    new_node.computed_style.color = .{ .r = 0, .g = 0, .b = 1, .a = 1 };
                }

                try current_node.children.append(new_node);

                if (html[tag_end] == ' ') {
                    var attr_start = tag_end + 1;
                    while (attr_start < html.len and html[attr_start] != '>') {
                        while (attr_start < html.len and html[attr_start] == ' ') : (attr_start += 1) {}
                        if (html[attr_start] == '>') break;

                        var attr_name_end = attr_start;
                        while (attr_name_end < html.len and html[attr_name_end] != '=' and html[attr_name_end] != ' ' and html[attr_name_end] != '>') : (attr_name_end += 1) {}

                        if (html[attr_name_end] == '=') {
                            const val_start = attr_name_end + 2; 
                            var val_end = val_start;
                            while (val_end < html.len and html[val_end] != '"') : (val_end += 1) {}
                            attr_start = val_end + 1;
                        } else {
                            attr_start = attr_name_end;
                        }
                    }
                    tag_end = attr_start;
                }

                if (!isVoidTag(tag_name)) {
                    current_node = new_node;
                }

                while (tag_end < html.len and html[tag_end] != '>') : (tag_end += 1) {}
                i = tag_end + 1;
            }
        } else {
            var text_end = i;
            while (text_end < html.len and html[text_end] != '<') : (text_end += 1) {}

            const text = std.mem.trim(u8, html[i..text_end], " \t\n\r");
            if (text.len > 0) {
                var text_node = try types.Node.init(allocator);
                text_node.type = .Text;
                text_node.text_content = try allocator.dupe(u8, text);
                text_node.parent = current_node;
                try current_node.children.append(text_node);
            }
            i = text_end;
        }
    }

    return root;
}

fn isVoidTag(tag: []const u8) bool {
    if (std.mem.eql(u8, tag, "img")) return true;
    if (std.mem.eql(u8, tag, "br")) return true;
    if (std.mem.eql(u8, tag, "input")) return true;
    if (std.mem.eql(u8, tag, "meta")) return true;
    if (std.mem.eql(u8, tag, "link")) return true;
    if (std.mem.eql(u8, tag, "hr")) return true;
    return false;
}
