const std = @import("std");
const mach = @import("mach");
const types = @import("types.zig");

pub const App = struct {
    engine: *mach.Core,
    pipeline: mach.gpu.RenderPipeline,
    queue: *mach.gpu.Queue,
    vertex_buffer: ?mach.gpu.Buffer,
    vertex_count: u32,

    pub fn init(engine: *mach.Core) !App {
        const shader_module = engine.device.createShaderModule(&.{
            .label = "ui_shader",
            .code = .{ .wgsl = 
                \\struct VertexOutput {
                \\    @builtin(position) position: vec4<f32>,
                \\    @location(0) color: vec4<f32>,
                \\};
                \\
                \\@vertex fn vs_main(
                \\    @location(0) position: vec2<f32>,
                \\    @location(1) color: vec4<f32>,
                \\    @location(2) screen_size: vec2<f32>
                \\) -> VertexOutput {
                \\    var output: VertexOutput;
                \\    let x_ndc = (position.x / screen_size.x) * 2.0 - 1.0;
                \\    let y_ndc = (1.0 - (position.y / screen_size.y)) * 2.0 - 1.0;
                \\    output.position = vec4<f32>(x_ndc, y_ndc, 0.0, 1.0);
                \\    output.color = color;
                \\    return output;
                \\}
                \\
                \\@fragment fn fs_main(@location(0) color: vec4<f32>) -> @location(0) vec4<f32> {
                \\    return color;
                \\}
            },
        });
        defer shader_module.release();

        const pipeline_layout = engine.device.createPipelineLayout(&.{
            .bind_group_layouts = &.{},
        });
        defer pipeline_layout.release();

        const pipeline = engine.device.createRenderPipeline(&.{
            .label = "render_pipeline",
            .layout = pipeline_layout,
            .vertex = .{
                .module = shader_module,
                .entry_point = "vs_main",
                .buffers = &.{
                    .{
                        .array_stride = 6 * @sizeOf(f32),
                        .step_mode = .vertex,
                        .attributes = &.{
                            .{ .format = .float32x2, .offset = 0, .shader_location = 0 }, 
                            .{ .format = .float32x4, .offset = 2 * @sizeOf(f32), .shader_location = 1 },
                        },
                    }
                },
            },
            .fragment = &.{
                .module = shader_module,
                .entry_point = "fs_main",
                .targets = &.{.{ .format = engine.descriptor.format }},
            },
        });

        return App{
            .engine = engine,
            .pipeline = pipeline,
            .queue = engine.device.getQueue(),
            .vertex_buffer = null,
            .vertex_count = 0,
        };
    }

    pub fn deinit(self: *App) void {
        self.pipeline.release();
        self.queue.release();
        if (self.vertex_buffer) |buf| buf.release();
    }

    pub fn prepareGeometry(self: *App, root: *types.Node) !void {
        var vertices = std.ArrayList(f32).init(std.heap.page_allocator);
        defer vertices.deinit();

        try self.traverseAndBuild(root, &vertices);

        if (self.vertex_buffer) |buf| buf.release();

        self.vertex_count = @intCast(vertices.items.len / 6);
        self.vertex_buffer = self.engine.device.createBuffer(&.{
            .label = "ui_vertices",
            .usage = .{ .vertex = true, .copy_dst = true },
            .size = vertices.items.len * @sizeOf(f32),
            .mapped_at_creation = false,
        });

        self.queue.writeBuffer(self.vertex_buffer.?, 0, vertices.items);
    }

    fn traverseAndBuild(self: *App, node: *types.Node, list: *std.ArrayList(f32)) !void {
        if (node.layout_box.width > 0 and node.layout_box.height > 0) {
            const x = node.layout_box.x;
            const y = node.layout_box.y;
            const w = node.layout_box.width;
            const h = node.layout_box.height;
            const c = node.computed_style.background_color;

            const quad = [_]f32{
                x, y,         c.r, c.g, c.b, c.a,
                x + w, y,     c.r, c.g, c.b, c.a,
                x, y + h,     c.r, c.g, c.b, c.a,
                x + w, y,     c.r, c.g, c.b, c.a,
                x + w, y + h, c.r, c.g, c.b, c.a,
                x, y + h,     c.r, c.g, c.b, c.a,
            };
            try list.appendSlice(&quad);
        }

        for (node.children.items) |child| {
            try self.traverseAndBuild(child, list);
        }
    }

    pub fn update(self: *App) !bool {
        const encoder = self.engine.device.createCommandEncoder(null);
        defer encoder.release();

        const back_buffer_view = self.engine.swap_chain.getCurrentTextureView();
        defer back_buffer_view.release();

        const color_attachment = mach.gpu.RenderPassColorAttachment{
            .view = back_buffer_view,
            .load_op = .clear,
            .store_op = .store,
            .clear_value = .{ .r = 1.0, .g = 1.0, .b = 1.0, .a = 1.0 },
        };

        const render_pass = encoder.beginRenderPass(&.{
            .color_attachments = &.{color_attachment},
        });

        if (self.vertex_buffer) |buf| {
            render_pass.setPipeline(self.pipeline);
            render_pass.setVertexBuffer(0, buf, 0, self.vertex_count * 6 * @sizeOf(f32));
            render_pass.draw(self.vertex_count, 1, 0, 0);
        }

        render_pass.end();
        render_pass.release();

        const command_buffer = encoder.finish(null);
        defer command_buffer.release();

        self.queue.submit(&.{command_buffer});
        self.engine.swap_chain.present();

        return false;
    }
};
