const std = @import("std");
const types = @import("types.zig");
const utils = @import("utils.zig");

pub fn parseInlineStyle(style_str: []const u8, style: *types.Style) void {
    var it = std.mem.splitScalar(u8, style_str, ';');
    while (it.next()) |decl| {
        const trimmed_decl = std.mem.trim(u8, decl, " \t\n\r");
        if (trimmed_decl.len == 0) continue;

        var parts = std.mem.splitScalar(u8, trimmed_decl, ':');
        const property = parts.next();
        const value = parts.next();

        if (property != null and value != null) {
            const prop = std.mem.trim(u8, property.?, " \t\n\r");
            const val = std.mem.trim(u8, value.?, " \t\n\r");

            if (std.mem.eql(u8, prop, "display")) {
                style.display = utils.parseDisplay(val);
            } else if (std.mem.eql(u8, prop, "background-color")) {
                style.background_color = utils.parseColorHex(val);
            } else if (std.mem.eql(u8, prop, "color")) {
                style.color = utils.parseColorHex(val);
            } else if (std.mem.eql(u8, prop, "font-size")) {
                style.font_size = utils.parseFloat(val);
            } else if (std.mem.eql(u8, prop, "margin")) {
                style.margin = utils.parseFloat(val);
            } else if (std.mem.eql(u8, prop, "padding")) {
                style.padding = utils.parseFloat(val);
            } else if (std.mem.eql(u8, prop, "width")) {
                style.width = utils.parseFloat(val);
            } else if (std.mem.eql(u8, prop, "height")) {
                style.height = utils.parseFloat(val);
            }
        }
    }
}

pub fn applyDefaultStyles(node: *types.Node) void {
    if (std.mem.eql(u8, node.tag, "div")) {
        node.computed_style.display = .Block;
    } else if (std.mem.eql(u8, node.tag, "span")) {
        node.computed_style.display = .Inline;
    } else if (std.mem.eql(u8, node.tag, "a")) {
        node.computed_style.display = .Inline;
        node.computed_style.color = .{ .r = 0, .g = 0, .b = 1, .a = 1 };
    } else if (std.mem.eql(u8, node.tag, "p")) {
        node.computed_style.display = .Block;
        node.computed_style.margin = 16;
    } else if (std.mem.eql(u8, node.tag, "h1")) {
        node.computed_style.display = .Block;
        node.computed_style.font_size = 32;
        node.computed_style.margin = 21;
    } else if (std.mem.eql(u8, node.tag, "body")) {
        node.computed_style.display = .Block;
        node.computed_style.margin = 8;
    }
}
