const std = @import("std");
const types = @import("types.zig");

pub const InputManager = struct {
    focused_node: ?*types.Node,

    pub fn init() InputManager {
        return InputManager{
            .focused_node = null,
        };
    }

    pub fn handleMouseClick(self: *InputManager, root: *types.Node, x: f32, y: f32) ?*types.Node {
        const target = self.hitTest(root, x, y);
        if (target) |node| {
            self.focused_node = node;
            return node;
        }
        return null;
    }

    fn hitTest(self: *InputManager, node: *types.Node, x: f32, y: f32) ?*types.Node {
        if (!rectContains(node.layout_box, x, y)) {
            return null;
        }

        var i = node.children.items.len;
        while (i > 0) {
            i -= 1;
            const child = node.children.items[i];
            const hit = self.hitTest(child, x, y);
            if (hit != null) {
                return hit;
            }
        }

        return node;
    }

    fn rectContains(rect: types.Rect, x: f32, y: f32) bool {
        return x >= rect.x and x <= rect.x + rect.width and
               y >= rect.y and y <= rect.y + rect.height;
    }
};
