const std = @import("std");
const mach = @import("mach");

pub const GlyphInfo = struct {
    x: f32,
    y: f32,
    w: f32,
    h: f32,
    u_min: f32,
    v_min: f32,
    u_max: f32,
    v_max: f32,
    advance: f32,
};

pub const FontManager = struct {
    allocator: std.mem.Allocator,
    texture: ?mach.gpu.Texture,
    glyphs: std.AutoHashMap(u8, GlyphInfo),
    device: *mach.gpu.Device,
    queue: *mach.gpu.Queue,

    pub fn init(allocator: std.mem.Allocator, device: *mach.gpu.Device, queue: *mach.gpu.Queue) !FontManager {
        var manager = FontManager{
            .allocator = allocator,
            .texture = null,
            .glyphs = std.AutoHashMap(u8, GlyphInfo).init(allocator),
            .device = device,
            .queue = queue,
        };
        try manager.loadDefaultFont();
        return manager;
    }

    pub fn deinit(self: *FontManager) void {
        if (self.texture) |tex| tex.release();
        self.glyphs.deinit();
    }

    fn loadDefaultFont(self: *FontManager) !void {
        const width = 128;
        const height = 128;
        const texture_size = mach.gpu.Extent3D{ .width = width, .height = height, .depth_or_array_layers = 1 };

        self.texture = self.device.createTexture(&.{
            .label = "font_atlas",
            .size = texture_size,
            .format = .r8_unorm,
            .usage = .{ .texture_binding = true, .copy_dst = true },
        });

        const bitmap = try self.allocator.alloc(u8, width * height);
        defer self.allocator.free(bitmap);

        @memset(bitmap, 0);

        var current_x: u32 = 0;
        var current_y: u32 = 0;
        const char_w = 8;
        const char_h = 16;

        var i: u8 = 32;
        while (i < 127) : (i += 1) {
            if (current_x + char_w > width) {
                current_x = 0;
                current_y += char_h;
            }

            for (0..char_h) |y| {
                for (0..char_w) |x| {
                    if (x > 1 and x < 6 and y > 2 and y < 13) {
                         const pixel_idx = (current_y + y) * width + (current_x + x);
                         bitmap[pixel_idx] = 255;
                    }
                }
            }

            const info = GlyphInfo{
                .x = @floatFromInt(current_x),
                .y = @floatFromInt(current_y),
                .w = @floatFromInt(char_w),
                .h = @floatFromInt(char_h),
                .u_min = @as(f32, @floatFromInt(current_x)) / @as(f32, @floatFromInt(width)),
                .v_min = @as(f32, @floatFromInt(current_y)) / @as(f32, @floatFromInt(height)),
                .u_max = @as(f32, @floatFromInt(current_x + char_w)) / @as(f32, @floatFromInt(width)),
                .v_max = @as(f32, @floatFromInt(current_y + char_h)) / @as(f32, @floatFromInt(height)),
                .advance = @floatFromInt(char_w + 1),
            };

            try self.glyphs.put(i, info);
            current_x += char_w;
        }

        self.queue.writeTexture(
            &.{ .texture = self.texture.? },
            &.{
                .bytes_per_row = width,
                .rows_per_image = height,
            },
            &texture_size,
            bitmap,
        );
    }

    pub fn getGlyph(self: *FontManager, char: u8) GlyphInfo {
        return self.glyphs.get(char) orelse self.glyphs.get('?').?;
    }
};
