const std = @import("std");
const mach = @import("mach");
const font_manager = @import("font_manager.zig");
const types = @import("types.zig");

pub const TextRenderer = struct {
    font_mgr: *font_manager.FontManager,
    vertex_buffer: ?mach.gpu.Buffer,
    pipeline: mach.gpu.RenderPipeline,
    bind_group: mach.gpu.BindGroup,
    vertex_count: u32,

    pub fn init(engine: *mach.Core, font_mgr: *font_manager.FontManager) !TextRenderer {
        const shader_module = engine.device.createShaderModule(&.{
            .label = "text_shader",
            .code = .{ .wgsl = 
                \\struct VertexOutput {
                \\    @builtin(position) position: vec4<f32>,
                \\    @location(0) tex_coords: vec2<f32>,
                \\    @location(1) color: vec4<f32>,
                \\};
                \\
                \\@group(0) @binding(0) var font_tex: texture_2d<f32>;
                \\@group(0) @binding(1) var font_sampler: sampler;
                \\
                \\@vertex fn vs_main(
                \\    @location(0) pos: vec2<f32>,
                \\    @location(1) uv: vec2<f32>,
                \\    @location(2) color: vec4<f32>,
                \\    @location(3) screen: vec2<f32>
                \\) -> VertexOutput {
                \\    var out: VertexOutput;
                \\    let x = (pos.x / screen.x) * 2.0 - 1.0;
                \\    let y = (1.0 - (pos.y / screen.y)) * 2.0 - 1.0;
                \\    out.position = vec4<f32>(x, y, 0.0, 1.0);
                \\    out.tex_coords = uv;
                \\    out.color = color;
                \\    return out;
                \\}
                \\
                \\@fragment fn fs_main(@location(0) uv: vec2<f32>, @location(1) color: vec4<f32>) -> @location(0) vec4<f32> {
                \\    let alpha = textureSample(font_tex, font_sampler, uv).r;
                \\    return vec4<f32>(color.rgb, color.a * alpha);
                \\}
            },
        });
        defer shader_module.release();

        const bind_group_layout = engine.device.createBindGroupLayout(&.{
            .entries = &.{
                .{
                    .binding = 0,
                    .visibility = .{ .fragment = true },
                    .texture = .{ .sample_type = .float },
                },
                .{
                    .binding = 1,
                    .visibility = .{ .fragment = true },
                    .sampler = .{ .type = .filtering },
                },
            },
        });
        defer bind_group_layout.release();

        const pipeline_layout = engine.device.createPipelineLayout(&.{
            .bind_group_layouts = &.{bind_group_layout},
        });
        defer pipeline_layout.release();

        const pipeline = engine.device.createRenderPipeline(&.{
            .label = "text_pipeline",
            .layout = pipeline_layout,
            .vertex = .{
                .module = shader_module,
                .entry_point = "vs_main",
                .buffers = &.{
                    .{
                        .array_stride = 8 * @sizeOf(f32),
                        .step_mode = .vertex,
                        .attributes = &.{
                            .{ .format = .float32x2, .offset = 0, .shader_location = 0 }, 
                            .{ .format = .float32x2, .offset = 8, .shader_location = 1 }, 
                            .{ .format = .float32x4, .offset = 16, .shader_location = 2 }, 
                        },
                    },
                },
            },
            .fragment = &.{
                .module = shader_module,
                .entry_point = "fs_main",
                .targets = &.{
                    .{ 
                        .format = engine.descriptor.format,
                        .blend = &.{
                            .color = .{ .src_factor = .src_alpha, .dst_factor = .one_minus_src_alpha, .operation = .add },
                            .alpha = .{ .src_factor = .one, .dst_factor = .one_minus_src_alpha, .operation = .add },
                        }
                    }
                },
            },
        });

        const sampler = engine.device.createSampler(&.{
            .mag_filter = .linear,
            .min_filter = .linear,
        });
        defer sampler.release();

        const bind_group = engine.device.createBindGroup(&.{
            .layout = bind_group_layout,
            .entries = &.{
                .{ .binding = 0, .texture_view = font_mgr.texture.?.createView(null) },
                .{ .binding = 1, .sampler = sampler },
            },
        });

        return TextRenderer{
            .font_mgr = font_mgr,
            .vertex_buffer = null,
            .pipeline = pipeline,
            .bind_group = bind_group,
            .vertex_count = 0,
        };
    }

    pub fn buildMesh(self: *TextRenderer, device: *mach.gpu.Device, queue: *mach.gpu.Queue, node: *types.Node) !void {
        var vertices = std.ArrayList(f32).init(std.heap.page_allocator);
        defer vertices.deinit();

        try self.traverseText(node, &vertices);

        if (self.vertex_buffer) |buf| buf.release();

        self.vertex_count = @intCast(vertices.items.len / 8);
        self.vertex_buffer = device.createBuffer(&.{
            .label = "text_vertices",
            .usage = .{ .vertex = true, .copy_dst = true },
            .size = vertices.items.len * @sizeOf(f32),
            .mapped_at_creation = false,
        });

        queue.writeBuffer(self.vertex_buffer.?, 0, vertices.items);
    }

    fn traverseText(self: *TextRenderer, node: *types.Node, list: *std.ArrayList(f32)) !void {
        if (node.type == .Text) {
            var cursor_x = node.layout_box.x;
            const cursor_y = node.layout_box.y;

            for (node.text_content) |char| {
                const glyph = self.font_mgr.getGlyph(char);
                const x0 = cursor_x;
                const y0 = cursor_y;
                const x1 = x0 + glyph.w;
                const y1 = y0 + glyph.h;
                const u0 = glyph.u_min;
                const v0 = glyph.v_min;
                const u1 = glyph.u_max;
                const v1 = glyph.v_max;

                const quad = [_]f32{
                    x0, y0, u0, v0, 0, 0, 0, 1,
                    x1, y0, u1, v0, 0, 0, 0, 1,
                    x0, y1, u0, v1, 0, 0, 0, 1,
                    x1, y0, u1, v0, 0, 0, 0, 1,
                    x1, y1, u1, v1, 0, 0, 0, 1,
                    x0, y1, u0, v1, 0, 0, 0, 1,
                };

                try list.appendSlice(&quad);
                cursor_x += glyph.advance;
            }
        }

        for (node.children.items) |child| {
            try self.traverseText(child, list);
        }
    }

    pub fn draw(self: *TextRenderer, render_pass: *mach.gpu.RenderPassEncoder) void {
        if (self.vertex_buffer) |buf| {
            render_pass.setPipeline(self.pipeline);
            render_pass.setBindGroup(0, self.bind_group, &.{});
            render_pass.setVertexBuffer(0, buf, 0, self.vertex_count * 8 * @sizeOf(f32));
            render_pass.draw(self.vertex_count, 1, 0, 0);
        }
    }

    pub fn deinit(self: *TextRenderer) void {
        if (self.vertex_buffer) |buf| buf.release();
        self.bind_group.release();
        self.pipeline.release();
    }
};
